/** Source of `.space/env.d.ts`, which gives `env` from `spacefn/env` the types of `env.ts`. */
export function generateEnvTypesSource(hasEnv: boolean): string {
	if (!hasEnv) return "// Generated by space. Do not edit.\nexport {};\n";
	return [
		"// Generated by space. Do not edit.",
		'import type { InferEnv } from "spacefn/env";',
		'import type schema from "../env";',
		"",
		'declare module "spacefn/env" {',
		"\tinterface Register {",
		"\t\tenv: InferEnv<typeof schema>;",
		"\t}",
		"}",
		"",
	].join("\n");
}
